export const MultipleItems: Story = {
  render: (args) => (
    <>
      <ProductItem {...args} product={MOCK_LINE_ITEM} primaryAction={<button type="button">Remove</button>} />
      <ProductItem {...args} product={MOCK_LINE_ITEM_TWO} primaryAction={<button type="button">Remove</button>} />
